const body = $json.body || $json;
if (!body.topic && !body.competitor) {
  throw new Error('Missing research topic or competitor parameter');
}
const query = (body.topic || body.competitor).trim();
return [{
  json: {
    research_id: 'res_' + Date.now(),
    query: query,
    depth: body.depth || 'deep',
    max_sources: body.max_sources || 10,
    initiated_at: new Date().toISOString()
  }
}];

const results = ($json.results || []).map(r => ({
  title: r.title,
  url: r.url,
  snippet: r.content,
  score: r.score
}));
return [{
  json: {
    raw_sources: results,
    source_count: results.length,
    query: $('Sanitize & Plan Query').item.json.query
  }
}];

